def data_source():
    for i in range(1, 6):
        yield i

def filter_even(numbers):
    for n in numbers:
        if n % 2 == 0:
            yield n

def square(numbers):
    for n in numbers:
        yield n ** 2

# 构建管道
pipeline = square(filter_even(data_source()))
for x in pipeline:
    print(x)
